#include "stdlib/complex/float64/base/mul.h"
#include "stdlib/complex/float64/ctor.h"
#include "stdlib/complex/float64/reim.h"

/**
* Multiplies two double-precision complex floating-point numbers.
*
* @param z1       input value
* @param z2       input value
* @return         result
*
* @example
* #include "stdlib/complex/float64/ctor.h"
* #include "stdlib/complex/float64/real.h"
* #include "stdlib/complex/float64/imag.h"
*
* stdlib_complex128_t z1 = stdlib_complex128( 5.0, 3.0 );
* stdlib_complex128_t z2 = stdlib_complex128( -2.0, 1.0 );
*
* stdlib_complex128_t out = stdlib_base_complex128_mul( z1, z2 );
*
* double re = stdlib_complex128_real( out );
* // returns -13.0
*
* double im = stdlib_complex128_imag( out );
* // returns -1.0
*/
stdlib_complex128_t stdlib_base_complex128_mul( const stdlib_complex128_t z1, const stdlib_complex128_t z2 ) {
	double re1;
	double re2;
	double im1;
	double im2;
	double re;
	double im;

	stdlib_complex128_reim( z1, &re1, &im1 );
	stdlib_complex128_reim( z2, &re2, &im2 );

	re = (re1*re2) - (im1*im2);
	im = (re1*im2) + (im1*re2);

	return stdlib_complex128( re, im );
}","lineStart":1,"lineEnd":61,"totalLines":61,"truncated":false}},"title":"repos\pc-lib-3456\complex-float64-base-mul\src\main.c","time":{"start":1783829009510,"end":1783829009545}},"id":"prt_f547e8e39001U7zHo3GysNcBLR","sessionID":"ses_0ab821990ffeePvYBLXl46cyJa","messageID":"msg_f547e3239001ai3Fet5fK77RRX"}}

